def generate_permutation(N):
    A = []
    left, right = 1, N
    for i in range(N):
        if i % 2 == 0:
            A.append(left)
            left += 1
        else:
            A.append(right)
            right -= 1
    return A

def main():
    T = int(input())
    for _ in range(T):
        N = int(input())
        A = generate_permutation(N)
        print(' '.join(map(str, A)))

if __name__ == "__main__":
    main()
